'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{execFileSync}=require('node:child_process'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const repo=path.resolve(__dirname,'../..'),root=process.env.MEMBRES_ORGANISATIONS_ASSET_DIR||repo,read=f=>fs.readFileSync(path.join(root,f),'utf8'),old=execFileSync('git',['show','1a5651a06fbb38600c3b453908b3bcbc832467fc:plateau-organisations-quetes.js'],{cwd:repo,encoding:'utf8',maxBuffer:4e6}),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
const selected=s=>{const n=parse(s).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='ouvrirGestionMembres');return s.slice(n.start,n.end);};
const escapeSource=(()=>{const s=read('forum.js'),n=parse(s).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='escapeHtmlText');return s.slice(n.start,n.end);})();
const member=(nom,grade='Membre',rejointLe=3)=>({nom,grade,rejointLe}),orga=(more={})=>({id:'fixture',nom:'Membres',chef:'Alice',type:'politique',membres:[member('Alice','Chef'),member('Bob','Cadre'),member('Camille')],...more});
const cases=[{id:'chef',orga:orga(),char:{name:'Alice'}},{id:'membre',orga:orga(),char:{name:'Bob'}},{id:'visiteur',orga:orga(),char:{name:'Autre'}},{id:'sans personnage',orga:orga(),char:null},{id:'vide',orga:orga({membres:[]}),char:{name:'Alice'}},{id:'type inconnu',orga:orga({type:'inconnu'}),char:{name:'Alice'}},{id:'chef absent',orga:orga({chef:'Absent'}),char:{name:'Alice'}},{id:'grade libre et jour zéro',orga:orga({membres:[member('Bob','Grand Maître — 原 اسم',0)]}),char:{name:'Alice'}},{id:'organisation absente',orga:null,char:{name:'Alice'}}];
async function setup(page,before=false){await page.route('**/*',r=>r.abort());await page.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><input id="draft" value="Brouillon conservé"><div id="modal-postes" class="modal-overlay"><div class="modal-box"><div class="modal-header"><div id="postes-modal-title" class="modal-title"></div><button class="modal-close" aria-label="Fermer">×</button></div><div id="postes-body" class="modal-body"></div></div></div></body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});await page.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.TYPES_ORGANISATIONS={politique:{grades:{republic:['Membre','Cadre','Chef']}}};window.state={country:'republic',pa:12,arg:4000,inventory:[{id:'intact'}],progression:{stage:3}};window.calls=[];window.lookups=[];window.getOrgaById=id=>{lookups.push(id);return state.orga;};for(const f of ['monterGrade','descendreGrade','exclureMembre'])window[f]=(...args)=>calls.push([f,...args]);for(const f of ['fetch','sbRpc','saveState','deduireCoutOrdre'])window[f]=(...args)=>{calls.push([f,...args]);throw Error('Appel métier inattendu');};window.snapshot=()=>JSON.stringify({state,calls,lookups});document.querySelector('.modal-close').onclick=()=>document.getElementById('modal-postes').classList.remove('open');});for(const f of ['i18n/resources.js','i18n/plateau-resources.js','i18n/sovarka-partis-resources.js','i18n/organization-members-resources.js','i18n/plateau-init.js'])await page.addScriptTag({content:read(f)});await page.addScriptTag({content:escapeSource+'\n'+selected(before?old:read('plateau-organisations-quetes.js'))});await page.evaluate(()=>i18next.changeLanguage('fr'));}
async function open(page,c){return page.evaluate(c=>{state.orga=c.orga;state.char=c.char;document.getElementById('postes-modal-title').textContent='Avant';document.getElementById('postes-body').textContent='Avant';document.getElementById('modal-postes').classList.remove('open');ouvrirGestionMembres(c.orga?.id||'absent');return {title:document.getElementById('postes-modal-title').textContent,body:document.getElementById('postes-body').textContent,buttons:[...document.querySelectorAll('#postes-body button')].map(e=>[e.textContent,e.title]),open:document.getElementById('modal-postes').className,state:JSON.stringify(state),lookups};},c);}
test('membres : français et droits identiques, neuf langues, 320/390/1280, noms/grades/position préservés et zéro dépense',async()=>{const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let count=0;try{for(const width of [320,390,1280]){const p=await browser.newPage({viewport:{width,height:900}}),before=await browser.newPage({viewport:{width,height:900}}),errors=[],requests=[];p.on('pageerror',e=>errors.push(String(e)));p.on('request',r=>requests.push(r.url()));await setup(p);await setup(before,true);
for(const c of cases){for(const page of [p,before])await page.evaluate(()=>i18next.changeLanguage('fr'));assert.deepEqual(await open(p,c),await open(before,c),c.id+' français entier/droits identiques');const snapshot=await p.evaluate(()=>snapshot()),nodes=await p.locator('#postes-body button').count();for(const lang of langs){await p.evaluate(lang=>i18next.changeLanguage(lang),lang);assert.equal(await p.evaluate(()=>snapshot()),snapshot);assert.equal(await p.locator('#postes-body button').count(),nodes);for(const node of await p.locator('#modal-postes [data-i18n]').all()){const key=await node.getAttribute('data-i18n');assert.equal(await node.textContent(),await p.evaluate(k=>i18next.t(k),key));assert.equal(await node.getAttribute('dir'),lang==='ar'?'rtl':null);}for(const node of await p.locator('#postes-body button').all()){const key=await node.getAttribute('data-i18n-title'),label=await p.evaluate(k=>i18next.t(k),key);assert.equal(await node.getAttribute('title'),label);assert.equal(await node.getAttribute('aria-label'),label);}assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await p.locator('.modal-box').evaluate(e=>e.scrollWidth>e.clientWidth),false);count++;}}
// Un clic ou Entrée garde exactement la cible, une seule commande intentionnelle.
for(const page of [p,before]){await open(page,cases[0]);for(let i=0;i<3;i++){await page.locator('#postes-body button').nth(i).click();await page.locator('#postes-body button').nth(i).focus();await page.keyboard.press('Enter');}}assert.deepEqual(await p.evaluate(()=>calls),await before.evaluate(()=>calls));assert.equal((await p.evaluate(()=>calls)).length,6);
// Même les noms contenant guillemets/balises ne deviennent pas des traductions ou du code.
const name=`O'Brien "<span data-i18n="toastTitles.error">原 اسم</span>`,group=`Organisation <img src=x onerror="fetch('interdit')">`,grade='<b>Grand Maître</b>';
await open(p,{orga:orga({id:`groupe'"`,nom:group,membres:[member(name,grade)]}),char:{name:'Alice'}});const opaque=await p.evaluate(()=>snapshot());for(const lang of langs){await p.evaluate(l=>i18next.changeLanguage(l),lang);const text=await p.locator('#postes-body').textContent();assert.ok(text.includes(name));assert.ok(text.includes(grade));assert.ok((await p.locator('#postes-modal-title').textContent()).includes(group));assert.equal(await p.locator('#postes-body b,#postes-body [data-i18n="toastTitles.error"],#postes-modal-title img').count(),0);assert.equal(await p.evaluate(()=>snapshot()),opaque);assert.equal(await p.locator('.modal-box').evaluate(e=>e.scrollWidth>e.clientWidth),false);}await p.locator('#postes-body button').first().click();assert.deepEqual(await p.evaluate(()=>calls.at(-1)),['monterGrade',`groupe'"`,name]);
await open(p,{orga:orga({membres:Array.from({length:40},(_,i)=>member('Personnage '+i))}),char:{name:'Bob'}});await p.locator('.hg-organisations > div').nth(20).scrollIntoViewIfNeeded();await p.evaluate(()=>{window.kept=document.querySelector('.hg-organisations').children[20];});const snap=await p.evaluate(()=>snapshot());for(const lang of langs){await p.evaluate(l=>i18next.changeLanguage(l),lang);assert.equal(await p.evaluate(()=>snapshot()),snap);assert.equal(await p.evaluate(()=>kept===document.querySelector('.hg-organisations').children[20]),true);assert.ok(await p.locator('.modal-box').evaluate(e=>e.scrollTop)>0);}
await open(p,cases[0]);await p.locator('#postes-body button').first().focus();const focus=await p.evaluate(()=>document.activeElement.getAttribute('onclick'));await p.evaluate(()=>i18next.changeLanguage('ar'));assert.equal(await p.evaluate(()=>document.activeElement.getAttribute('onclick')),focus);
for(let i=0;i<3;i++){await open(p,cases[0]);await p.locator('.modal-close').click();const s=await p.evaluate(()=>snapshot());await p.evaluate(()=>i18next.changeLanguage('de'));assert.equal(await p.locator('#modal-postes').evaluate(e=>e.classList.contains('open')),false);assert.equal(await p.evaluate(()=>snapshot()),s);}
await p.evaluate(()=>{document.getElementById('postes-modal-title').textContent='Fenêtre voisine';document.getElementById('postes-body').textContent='Autre corps';});await p.evaluate(()=>i18next.changeLanguage('ar'));assert.equal(await p.locator('#postes-modal-title').textContent(),'Fenêtre voisine');
await p.evaluate(()=>{delete i18next.getResourceBundle('de','translation').organizationMembers;});await open(p,cases[0]);await p.evaluate(()=>i18next.changeLanguage('de'));assert.equal(await p.locator('#postes-body button').first().getAttribute('title'),'Monter en grade');await p.evaluate(()=>{window.RPI18nPlateau=undefined;});const fallback=await open(p,cases[0]);assert.equal(fallback.title,'👥 Membres — Membres');assert.ok(fallback.body.includes('Depuis Jour '));assert.deepEqual(errors,[]);assert.deepEqual(requests,[]);await p.close();await before.close();}assert.equal(count,243);console.log('9 états, 243 bascules ; commandes intentionnelles identiques et noms opaques.');}finally{await browser.close();}});
